import{_ as r,o as t,c as i,ah as a}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/gericht-thomas-schmid.md","filePath":"recherche/gericht-thomas-schmid.md"}'),n={name:"recherche/gericht-thomas-schmid.md"};function s(h,e,o,l,d,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="gerichtliche-nachspiele-thomas-schmid-der-archivar-der-macht" tabindex="-1">Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht) <a class="header-anchor" href="#gerichtliche-nachspiele-thomas-schmid-der-archivar-der-macht" aria-label="Permalink to &quot;Gerichtliche Nachspiele: Thomas Schmid (Der Archivar der Macht)&quot;">​</a></h1><p><strong>Vom treuen Vertrauten zum wichtigsten Kronzeugen der Zweiten Republik.</strong></p><p>Thomas Schmid war der Mann im Zentrum des „Systems Kurz“. Als Generalsekretär im Finanzministerium und späterer ÖBAG-Chef verwaltete er nicht nur das Staatsvermögen, sondern auch die informellen Netzwerke der Macht. Seine sichergestellten Chats sind die „Rosetta-Steine“ der modernen österreichischen Korruptionsforschung.</p><hr><h2 id="die-rolle-im-system" tabindex="-1">Die Rolle im System <a class="header-anchor" href="#die-rolle-im-system" aria-label="Permalink to &quot;Die Rolle im System&quot;">​</a></h2><h3 id="_1-das-digitale-gedachtnis" tabindex="-1">1. Das digitale Gedächtnis <a class="header-anchor" href="#_1-das-digitale-gedachtnis" aria-label="Permalink to &quot;1. Das digitale Gedächtnis&quot;">​</a></h3><p>Die Sicherstellung seines Mobiltelefons (im Zuge der Ibiza-Ermittlungen) brachte über 300.000 Chat-Nachrichten ans Licht. Diese dokumentieren detailliert:</p><ul><li><strong>Postenschacher:</strong> „Kriegst eh alles, was du willst.“</li><li><strong>Umfragen-Manipulation:</strong> Das Beinschab-Österreich-Tool.</li><li><strong>Steuer-Interventionen:</strong> Wie Großinvestoren (wie René Benko) bevorzugt behandelt wurden.</li></ul><h3 id="_2-der-kronzeugenstatus-oktober-2022" tabindex="-1">2. Der Kronzeugenstatus (Oktober 2022) <a class="header-anchor" href="#_2-der-kronzeugenstatus-oktober-2022" aria-label="Permalink to &quot;2. Der Kronzeugenstatus (Oktober 2022)&quot;">​</a></h3><p>Nach monatelangen Befragungen durch die WKStA legte Thomas Schmid ein umfassendes Geständnis ab. Er belastete zahlreiche Spitzenpolitiker der ÖVP (darunter Sebastian Kurz und Wolfgang Sobotka) und strebt seither den offiziellen Kronzeugenstatus an.</p><hr><h2 id="die-verbindung-zum-horten-mysterium" tabindex="-1">Die Verbindung zum Horten-Mysterium <a class="header-anchor" href="#die-verbindung-zum-horten-mysterium" aria-label="Permalink to &quot;Die Verbindung zum Horten-Mysterium&quot;">​</a></h2><p>Thomas Schmid ist die akustische Brücke in unserem Projekt:</p><ul><li><strong>Die Benko-Achse:</strong> Schmid war die Anlaufstelle für René Benko im Finanzministerium, wenn es um steuerliche Erleichterungen oder COFAG-Hilfen ging.</li><li><strong>Die Horten-Spenden:</strong> Seine Chats liefern den Kontext zur „Ästhetik der Stückelung“. Er wusste, wie man Spenden so platziert, dass sie das System am Laufen halten, ohne Alarm auszulösen.</li></ul><hr><h2 id="status-2026" tabindex="-1">Status 2026 <a class="header-anchor" href="#status-2026" aria-label="Permalink to &quot;Status 2026&quot;">​</a></h2><p>Thomas Schmid bleibt die brisanteste Figur in den laufenden U-Ausschüssen und Strafverfahren. Seine Aussagen (insb. im Pilnacek-Ausschuss) sind die Munition für unsere satirische Aufarbeitung in Teil 4 des Drehbuchs.</p><hr><p><em>Quellen: Einvernahmeprotokolle der WKStA (2022-2024), Chat-Dossiers von ZackZack und Profil.</em></p>',19)])])}const g=r(n,[["render",s]]);export{m as __pageData,g as default};
